// Generated by the final SEO build step, after canonical-page validation.
// Routing Middleware supports Hobby, unlike Vercel Bulk Redirects.
import redirects from "./.vercel/stoppin-venue-redirects.mjs";
import restaurantRedirects from "./.vercel/restaurant-redirects.mjs";

export const config = { matcher: ["/restaurants-pres/:path*", "/restaurant/:path*"] };

const destinations = new Map([...redirects, ...restaurantRedirects].map(({ source, destination }) => [source, destination]));

export default function middleware(request) {
  if (!["GET", "HEAD"].includes(request.method)) return;
  const url = new URL(request.url);
  const destination = destinations.get(url.pathname);
  if (!destination) {
    // Unknown/nonpublic restaurant IDs must not return the homepage with HTTP
    // 200. No database lookup or private inventory is exposed at request time.
    if (/^\/restaurant\/[^/]+\/?$/.test(url.pathname)) {
      const body = '<!doctype html><html lang="fr-CH"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Restaurant introuvable | TOK</title></head><body><main><h1>Restaurant introuvable</h1><p>Cette fiche n’existe pas ou n’est plus disponible dans le catalogue public.</p><p><a href="/recherche">Rechercher un restaurant</a> · <a href="/">Accueil TOK</a></p></main></body></html>';
      return new Response(request.method === "HEAD" ? null : body, {
        status: 404,
        headers: { "Content-Type": "text/html; charset=utf-8", "X-Robots-Tag": "noindex, nofollow", "Cache-Control": "no-store" },
      });
    }
    return;
  }

  // Exact, case-sensitive lookup; preserve the query string and same origin.
  url.pathname = destination;
  return Response.redirect(url, 301);
}
